import {emptyData,validateBackup,parseMarkdown} from './model.js';
const $=s=>document.querySelector(s),config=window.ATTENTION_CONFIG,configured=/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(config.supabaseUrl)&&!!config.supabaseKey,demo=new URLSearchParams(location.search).get('demo')==='1';let session=null,data=emptyData(),revision=0,dirty=false,mode='login',busy=false,saveHandler;
const dateKey=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};$('#plan-date').value=dateKey(Date.now());
function el(tag,text,cls){const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n}function button(text,fn){const n=el('button',text);n.type='button';n.onclick=()=>run(fn);return n}function status(text){$('#sync-status').textContent=text}async function run(fn){if(busy)return;busy=true;try{await fn()}catch(e){status(e.message);$('#auth-message').textContent=e.message}finally{busy=false}}
async function request(path,body,auth=false,method='POST'){if(!configured)throw Error('Сначала нужно подключить проект Supabase.');if(auth&&session?.expires_at<Date.now()/1000+60){const refreshed=await request('/auth/v1/token?grant_type=refresh_token',{refresh_token:session.refresh_token});remember(refreshed)}const response=await fetch(config.supabaseUrl+path,{method,headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+session.access_token}:{})},...(body?{body:JSON.stringify(body)}:{})});const result=response.status===204?null:await response.json().catch(()=>null);if(!response.ok){if(result?.message?.includes('revision_conflict'))throw Error('На другом устройстве есть изменения. Экспортируйте текущий вариант, затем получите новую версию из облака.');throw Error(response.status===401?'Сессия завершилась или неверный email/пароль. Войдите снова.':result?.msg||result?.message||result?.error_description||'Сервис недоступен. Изменения не отправлены.')}return result}
function remember(s){session={...s,expires_at:s.expires_at||Date.now()/1000+s.expires_in};sessionStorage.setItem('attention-session',JSON.stringify(session))}
function mark(){dirty=true;$('#save-state').textContent=demo?'Сохранено в этом браузере':'Есть несохранённые изменения';if(demo){try{localStorage.setItem('attention-demo',JSON.stringify(data))}catch{status('Не удалось сохранить локально. Экспортируйте копию.')}}render()}
function openApp(){ $('#auth').hidden=true;$('#app').hidden=false;$('#identity').textContent=demo?'ЛОКАЛЬНЫЙ ПРОСМОТР':session.user.email;$('#cloud-save').hidden=demo;$('#cloud-load').hidden=demo;status(demo?'Локальный режим без аккаунта. Изменения сохраняются только в этом браузере и не синхронизируются.':'Данные аккаунта загружаются…');render()}
async function load(){const rows=await request('/rest/v1/attention_documents?select=payload,revision',null,true,'GET');data=rows.length?validateBackup(rows[0].payload):emptyData();revision=rows[0]?.revision||0;dirty=false;$('#save-state').textContent='Облачная версия '+revision;status('Данные получены из вашего аккаунта. После редактирования нажмите «Сохранить в облако».');render()}
$('#cloud-save').onclick=()=>run(async()=>{validateBackup(data);const r=await request('/rest/v1/rpc/attention_save',{expected_revision:revision,new_payload:data},true);revision=r;dirty=false;$('#save-state').textContent='Сохранено · версия '+revision;status('Изменения сохранены в вашем аккаунте.');});$('#cloud-load').onclick=()=>run(async()=>{if(!dirty||confirm('Заменить несохранённые изменения облачной версией?'))await load()});
$('#setup-notice').hidden=configured;$('#auth-submit').disabled=!configured;$('#forgot').disabled=!configured;
document.querySelectorAll('[data-mode]').forEach(n=>n.onclick=()=>{mode=n.dataset.mode;$('#auth-submit').textContent=mode==='login'?'Войти':'Создать аккаунт';$('#password').autocomplete=mode==='login'?'current-password':'new-password';$('#auth-message').textContent=''});
$('#auth-form').onsubmit=e=>{e.preventDefault();run(async()=>{const email=$('#email').value.trim(),password=$('#password').value;$('#auth-submit').disabled=true;try{if(mode==='recovery'){await request('/auth/v1/user',{password},true,'PUT');$('#auth-message').textContent='Пароль обновлён.';mode='login';openApp();await load();return}const r=await request(mode==='signup'?'/auth/v1/signup?redirect_to='+encodeURIComponent(new URL('./workspace.html', location.href).href):'/auth/v1/token?grant_type=password',{email,password});if(!r.access_token){$('#auth-message').textContent='Проверьте почту и подтвердите адрес. После подтверждения войдите.';return}remember(r);openApp();await load()}finally{$('#password').value='';$('#auth-submit').disabled=!configured}})};
$('#forgot').onclick=()=>run(async()=>{if(!$('#email').reportValidity())return;await request('/auth/v1/recover?redirect_to='+encodeURIComponent(new URL('./workspace.html', location.href).href),{email:$('#email').value.trim()});$('#auth-message').textContent='Если аккаунт существует, письмо для смены пароля отправлено.'});$('#logout').onclick=()=>run(async()=>{if(dirty&&!demo&&!confirm('Выйти без сохранения изменений?'))return;if(!demo)await request('/auth/v1/logout',{},true);sessionStorage.removeItem('attention-session');session=null;location.href='./workspace.html'});
document.querySelectorAll('[data-view]').forEach(n=>n.onclick=()=>{document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b===n));for(const v of ['plan','learning','data'])$('#'+v+'-view').hidden=v!==n.dataset.view});$('#plan-date').onchange=render;
function editor(title,fields,save){$('#editor-title').textContent=title;$('#editor-fields').replaceChildren();const inputs={};for(const f of fields){const label=el('label',f.label),input=document.createElement(f.type==='textarea'?'textarea':'input');if(f.type!=='textarea')input.type=f.type||'text';input.value=f.value??'';input.required=!!f.required;if(f.max)input.maxLength=f.max;if(f.min!=null)input.min=f.min;if(f.upper!=null)input.max=f.upper;label.append(input);$('#editor-fields').append(label);inputs[f.key]=input}saveHandler=()=>{const values=Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value.trim()]));if('title' in values&&!values.title)throw Error('Название не может быть пустым.');save(values);mark();$('#editor').close()};$('#editor').showModal()}$('#editor-form').onsubmit=e=>{e.preventDefault();try{saveHandler()}catch(e){alert(e.message)}};$('#close-editor').onclick=()=>$('#editor').close();
function editTask(t){const start=t?.start??+new Date($('#plan-date').value+'T09:00:00');editor(t?'Изменить дело':'Новое дело',[{key:'title',label:'Что хотите сделать?',value:t?.title,required:true,max:120},{key:'start',label:'Дата и время',type:'datetime-local',value:dateKey(start)+'T'+new Date(start).toTimeString().slice(0,5),required:true},{key:'minutes',label:'Продолжительность, минут',type:'number',min:1,upper:720,value:t?.minutes||50,required:true}],v=>{const updated={...(t||{id:crypto.randomUUID(),category:'Работа',status:'planned',autoFocus:false}),title:v.title,start:+new Date(v.start),minutes:Number(v.minutes)};if(!v.title||!Number.isFinite(updated.start))throw Error('Укажите название и время.');if(t)data.tasks=data.tasks.map(x=>x.id===t.id?updated:x);else data.tasks.push(updated)})}$('#add-task').onclick=()=>editTask();
function editStep(m,s){editor(s?'Шаг обучения':'Новый шаг',[{key:'title',label:'Тема',value:s?.title,max:240,required:true},{key:'date',label:'Дата (необязательно)',type:'date',value:s?.date?dateKey(s.date):'',min:'2000-01-01',upper:'2100-12-31'},{key:'comment',label:'Комментарий',type:'textarea',value:s?.comment,max:5000},{key:'note',label:'Материалы',type:'textarea',value:s?.note,max:10000}],v=>{const step={...(s||{id:crypto.randomUUID(),done:false,section:'',level:0}),...v,date:v.date?+new Date(v.date+'T00:00:00'):null};if(s)m.steps=m.steps.map(x=>x.id===s.id?step:x);else m.steps.push(step)})}
function render(){const tasks=$('#tasks');tasks.replaceChildren();const list=data.tasks.filter(t=>dateKey(t.start)===$('#plan-date').value&&t.status!=='cancelled').sort((a,b)=>a.start-b.start);if(!list.length)tasks.append(el('p','Пока свободно. Начните с одного понятного дела.','empty'));for(const t of list){const row=el('div',null,'task-row'),check=document.createElement('input');check.type='checkbox';check.checked=t.status==='completed';check.setAttribute('aria-label','Выполнено: '+t.title);check.onchange=()=>{t.status=check.checked?'completed':'planned';mark()};const text=el('div');text.append(el('span',t.title,check.checked?'complete':''),el('small',new Date(t.start).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})+' · '+t.minutes+' мин'));row.append(check,text,button('Изменить',()=>editTask(t)),button('×',()=>{if(confirm('Удалить «'+t.title+'»?')){data.tasks=data.tasks.filter(x=>x.id!==t.id);mark()}}));tasks.append(row)}const maps=$('#roadmaps');maps.replaceChildren();if(!data.roadmaps.length)maps.append(el('p','Создайте учебный путь или импортируйте Markdown из Obsidian.','empty'));for(const m of data.roadmaps){const group=el('article',null,'roadmap-group');group.append(el('h3',m.title),el('p',`${m.steps.filter(s=>s.done).length} из ${m.steps.length} шагов`,'micro'));const controls=el('div',null,'toolbar');controls.append(button('+ Шаг',()=>editStep(m)),button('Название',()=>editor('Роадмапа',[{key:'title',label:'Название',value:m.title,required:true,max:120}],v=>m.title=v.title)),button('Удалить',()=>{if(confirm('Удалить роадмапу со всеми шагами?')){data.roadmaps=data.roadmaps.filter(x=>x.id!==m.id);mark()}}));group.append(controls);for(const s of m.steps){const row=el('div',null,'task-row'),check=document.createElement('input');check.type='checkbox';check.checked=s.done;check.setAttribute('aria-label','Изучено: '+s.title);check.onchange=()=>{s.done=check.checked;mark()};const text=el('div');text.append(el('span',s.title,s.done?'complete':''),el('small',[s.section,s.date?new Date(s.date).toLocaleDateString('ru'):'Без даты',s.comment].filter(Boolean).join(' · ')));row.append(check,text,button('Править',()=>editStep(m,s)),button('×',()=>{if(confirm('Удалить шаг?')){m.steps=m.steps.filter(x=>x.id!==s.id);mark()}}));group.append(row)}maps.append(group)}}
$('#add-roadmap').onclick=()=>editor('Новый путь',[{key:'title',label:'Что хотите изучить?',required:true,max:120}],v=>data.roadmaps.push({id:crypto.randomUUID(),title:v.title,steps:[],description:'',source:''}));
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify({...data,createdAt:new Date().toISOString()},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='attention-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#export').onclick=exportData;
let importKind;function choose(kind){importKind=kind;$('#file-input').accept=kind==='markdown'?'.md,.markdown,.txt':'.json';$('#file-input').value='';$('#file-input').click()}$('#import-markdown').onclick=()=>choose('markdown');$('#import-backup').onclick=()=>choose('backup');$('#cancel-import').onclick=()=>$('#preview').close();$('#file-input').onchange=()=>run(async()=>{const file=$('#file-input').files[0];if(!file)return;if(file.size>(importKind==='markdown'?2:10)*1024*1024)throw Error('Файл слишком большой.');const text=await file.text(),parsed=importKind==='markdown'?parseMarkdown(text,file.name):validateBackup(JSON.parse(text)),kind=importKind;$('#preview-label').textContent=kind==='markdown'?`${parsed.title} · ${parsed.steps.length} шагов. Будет создана отдельная роадмапа.`:`${parsed.tasks.length} дел, ${parsed.roadmaps.length} роадмап. Текущее пространство будет заменено. Сначала экспортируйте нужные данные.`;$('#preview-content').textContent=kind==='markdown'?parsed.steps.map(s=>(s.done?'✓ ':'□ ')+s.title+(s.date?' · '+dateKey(s.date):' · без даты')).join('\n'):parsed.tasks.slice(0,20).map(t=>t.title).join('\n');$('#accept-import').onclick=()=>{if(kind==='markdown')data.roadmaps.push(parsed);else data=parsed;mark();$('#preview').close()};$('#preview').showModal()});
window.addEventListener('beforeunload',e=>{if(dirty&&!demo){e.preventDefault();e.returnValue=''}});
if(demo){try{data=validateBackup(JSON.parse(localStorage.getItem('attention-demo')))}catch{data=emptyData()}openApp()}else if(configured){run(async()=>{const params=new URLSearchParams(location.hash.slice(1));if(params.get('access_token')){session={access_token:params.get('access_token'),refresh_token:params.get('refresh_token'),expires_at:Date.now()/1000+Number(params.get('expires_in')||3600)};const recovery=params.get('type')==='recovery';history.replaceState(null,'',location.pathname);const user=await request('/auth/v1/user',null,true,'GET');remember({...session,user});if(recovery){mode='recovery';$('#auth-submit').textContent='Сохранить новый пароль';$('#email').value=user.email;$('#email').readOnly=true;$('#password').autocomplete='new-password';$('#auth-message').textContent='Задайте новый пароль.';return}}else{try{session=JSON.parse(sessionStorage.getItem('attention-session'))}catch{session=null}}if(session){session.user=await request('/auth/v1/user',null,true,'GET');openApp();await load()}})}
